import React from "react";

// ─────────────────────────────────────────────
// HELPER — applies universal Svg defaults (xmlns, size, viewBox, fill)
// plus an optional colored background box, so individual icons only
// need to define their <path> — nothing else is repeated.
// Fill defaults to currentColor so Tailwind text-* classes still control color.
// ─────────────────────────────────────────────
interface IconProps extends Omit<React.SVGProps<SVGSVGElement>, "color" | "size"> {
  size?: number;
  color?: string;
  backgroundColor?: string;
  padding?: number;
  borderRadius?: number;
}

const withBackground = (IconPath: React.FC) =>
  ({ backgroundColor, size = 26, color = "currentColor", padding = 0, borderRadius = 8, ...props }: IconProps) => {
    const svg = (
      <svg
        xmlns="http://www.w3.org/2000/svg"
        width={size}
        height={size}
        fill={color}
        viewBox="0 0 256 256"
        aria-hidden="true"
        {...props}
      >
        <IconPath />
      </svg>
    );

    // No background requested → return the bare svg so layout stays untouched
    if (!backgroundColor) return svg;

    return (
      <div
        style={{
          backgroundColor,
          borderRadius,
          padding,
          display: "inline-flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        {svg}
      </div>
    );
  };

